const KEMPTY_COORDS=[30.4833,78.0333],HEIGHT_COMPARISONS=[{name:"Kempty Falls (total drop)",heightMeters:15,note:"~40-50 ft drop across five cascading tiers"},{name:"Average 4-storey building",heightMeters:12,note:"For scale, a typical four-storey building"},{name:"Qutub Minar (Delhi)",heightMeters:73,note:"Tallest brick minaret in the world, for comparison"},{name:"Jog Falls (Karnataka)",heightMeters:253,note:"India's highest un-tiered waterfall"}],TIER_STAGES=[{stage:"1",title:"Source Spring",img:"https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&q=80&w=800",alt:"A clear mountain spring stream flowing through a forested Himalayan hillside",text:"The water begins as a perennial spring-fed stream gathering near Banglow ki Kandi, on the ridges southwest of Kempty village, high in the Garhwal Himalayas."},{stage:"2",title:"First Tier",img:"https://images.unsplash.com/photo-1508739773434-c26b3d09e071?auto=format&fit=crop&q=80&w=800",alt:"Water beginning to cascade over the first rocky step of a hillside stream",text:"As the stream turns northwest off the ridge, it meets its first rocky step, picking up speed and breaking into white water for the first time."},{stage:"3",title:"Middle Cascades",img:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",alt:"A multi-tiered waterfall cascading over several rocky ledges",text:"The stream splits and rejoins across a series of smaller ledges — locally counted as five cascades in total — each adding mist and noise to the descent."},{stage:"4",title:"Main Drop",img:"https://images.unsplash.com/photo-1467890947394-8171244e5410?auto=format&fit=crop&q=80&w=800",alt:"The main waterfall drop of Kempty Falls plunging toward the pool below",text:"The final and largest step sends the water plunging roughly 40 feet down a cliff face, the sight most visitors photograph from the road above."},{stage:"5",title:"Pool Below",img:"https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&q=80&w=800",alt:"A natural rock pool at the base of a waterfall where visitors bathe",text:"At the base, the water collects in a rock pool and a man-made pond popular for bathing and boating, before continuing downhill to join the Yamuna about 12 km further on."}],SEASONAL_DATA=[{season:"Monsoon (Jul–Aug)",badgeClass:"badge-monsoon",img:"https://images.unsplash.com/photo-1622401467213-a2fecad55b93?auto=format&fit=crop&q=80&w=600",alt:"A waterfall in heavy, powerful monsoon flow",title:"Heavy & Hazardous",text:"The stream swells dramatically and the current below the falls becomes strong enough that authorities often restrict bathing. Spectacular to view, best avoided for swimming."},{season:"Autumn–Spring (Sep–Jun)",badgeClass:"badge-winter",img:"https://images.unsplash.com/photo-1601582589907-f92af5ed9db8?auto=format&fit=crop&q=80&w=600",alt:"A calm, clear waterfall flowing gently over rocks in cool weather",title:"Clear & Comfortable",text:"Flow steadies into a clear, manageable cascade. Cool, pleasant weather makes March–June and September–November the recommended window to visit and bathe."}],VIEWPOINTS=[{title:"Roadside Overlook",img:"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&q=80&w=700",alt:"A scenic overlook above a Himalayan waterfall from a mountain road",text:"The Mussoorie–Yamunotri road runs right past the falls, giving an immediate first view of the main drop and the pool below."},{title:"Ropeway / Cable Car",img:"https://images.unsplash.com/photo-1605540436563-5bca919ae766?auto=format&fit=crop&q=80&w=700",alt:"A cable car ropeway descending a forested hillside toward a waterfall",text:"A cable-car ropeway carries visitors down the hillside to the base of the falls, offering an aerial view of all five cascades and the surrounding valley."},{title:"Pool-Level Viewing Steps",img:"https://images.unsplash.com/photo-1470770903676-69b98201ea1c?auto=format&fit=crop&q=80&w=700",alt:"Stone steps leading down to a waterfall pool for close viewing",text:"Stairs beside the falls lead down to the water's edge, putting visitors within reach of the spray for the closest possible view."}],GALLERY_IMAGES=[{url:"https://images.unsplash.com/photo-1467890947394-8171244e5410?auto=format&fit=crop&q=80&w=800",caption:"Kempty Falls dropping through its final tier toward the pool below",category:"Hero Plunge"},{url:"https://images.unsplash.com/photo-1470770903676-69b98201ea1c?auto=format&fit=crop&q=80&w=800",caption:"Close-up of white water breaking over rock at Kempty Falls",category:"Waterfall Close-up"},{url:"https://images.unsplash.com/photo-1626621331169-5f34be280ed9?auto=format&fit=crop&q=80&w=800",caption:"Pine and deodar-forested Garhwal Himalayan ridgeline around Mussoorie",category:"Mountain Landscape"},{url:"https://images.unsplash.com/photo-1605540436563-5bca919ae766?auto=format&fit=crop&q=80&w=800",caption:"View of the falls and valley from the ropeway viewpoint",category:"Viewpoint"}],NEARBY_ATTRACTIONS=[{name:"Mussoorie Mall Road",distance:"15 km",lat:30.4598,lng:78.0664,description:"The bustling heart of Mussoorie, lined with shops, cafes and viewpoints over the Doon Valley."},{name:"Camel's Back Road",distance:"16 km",lat:30.461,lng:78.074,description:"A gentle walking trail around a rock formation shaped like a camel's hump, popular at sunset."},{name:"Lal Tibba",distance:"18 km",lat:30.4735,lng:78.0921,description:"Mussoorie's highest point, with telescope views of the snow-capped Himalayan range on clear days."},{name:"Jharipani Falls",distance:"10 km",lat:30.4326,lng:78.0684,description:"A quieter, less-visited waterfall on the Mussoorie–Dehradun road, framed by pine forest."}],REFERENCES=[{text:"Wikipedia — Kempty Falls, Tehri Garhwal District, Uttarakhand.",link:"https://en.wikipedia.org/wiki/Kempty_Falls"},{text:"Uttarakhand Tourism (eUttaranchal) — Kempty Falls, Mussoorie.",link:"https://www.euttaranchal.com/tourism/kempty-falls.php"},{text:"Incredible India (Government of India) — Kempty Falls, Mussoorie.",link:"https://www.incredibleindia.gov.in/en/uttarakhand/mussoorie/kempty-falls"},{text:"Images: Unsplash contributors (used under the Unsplash License for demonstration purposes).",link:"https://unsplash.com/license"}];"undefined"!=typeof module&&module.exports&&(module.exports={KEMPTY_COORDS:KEMPTY_COORDS,HEIGHT_COMPARISONS:HEIGHT_COMPARISONS,TIER_STAGES:TIER_STAGES,SEASONAL_DATA:SEASONAL_DATA,VIEWPOINTS:VIEWPOINTS,GALLERY_IMAGES:GALLERY_IMAGES,NEARBY_ATTRACTIONS:NEARBY_ATTRACTIONS,REFERENCES:REFERENCES});